#' Predict using the twdtw_knn1 model
#'
#' This function predicts the classes of new data using the Time Warped Dynamic Time Warping (TWDTW)
#' method with a 1-nearest neighbor approach. The prediction is based on the minimum TWDTW distance
#' to the known patterns stored in the `twdtw_knn1` model.
#'
#' @param object A `twdtw_knn1` model object generated by the `twdtw_knn1` function.
#' @param newdata The new observations (time series data) to be predicted. Either a
#' three-dimensional stars object (x, y, time) with bands as attributes, or a data frame with
#' one row for each time series and one column for each band and date, named with the band
#' and the date, e.g. `EVI.2011-09-14`. This is the data frame that \link[stars]{predict.stars}
#' passes to this function, see details.
#' @param ... Arguments of the TWDTW distance that replace the arguments passed to
#' \link[dtwSat]{twdtw_knn1}: `time_weight`, `cycle_length`, `time_scale`, `origin`, and `max_elapsed`.
#'
#' @details There are two ways to classify a data cube `x`, i.e. a three-dimensional stars
#' object (x, y, time) with bands as attributes. Both return a stars object with the spatial
#' dimensions of the data cube and the attributes `prediction` and `distance`.
#' They differ in the pixels with missing values:
#'
#' \itemize{
#'   \item `predict(object, newdata = x)` classifies all pixels. An observation with a
#'   missing value in any band is not used, and the pixel is classified with its remaining
#'   observations. Only a pixel without any complete observation has `NA` as prediction
#'   and distance.
#'   \item `predict(x, model = object)` calls \link[stars]{predict.stars}, as for other
#'   models, and does not classify pixels with missing values. stars replaces the missing
#'   values with zeros, passes the data to this function, and then sets the result of every
#'   pixel that had a missing value in any band or date to `NA`. The zeros are therefore not
#'   part of the result, but a single missing value is enough for a pixel to have no prediction.
#' }
#'
#' The TWDTW distances between all time series and all temporal patterns are calculated in
#' a single call to \link[twdtw]{twdtw_knn}.
#'
#' @return If `newdata` is a stars object, a stars object with the spatial dimensions of
#' `newdata` and two attributes: `prediction`, a factor with the label of the nearest
#' temporal pattern, and `distance`, the TWDTW distance to this pattern.
#' If `newdata` is a data frame, a data frame with one row for each time series and
#' the columns `prediction` and `distance`.
#'
#' @seealso twdtw_knn1
#'
#' @inherit twdtw_knn1 examples
#'
#' @export
predict.twdtw_knn1 <- function(object, newdata, ...){

  # Update twdtw_args with new arguments passed via ...
  new_twdtw_args <- list(...)
  matching_twdtw_args <- intersect(names(new_twdtw_args), names(object$twdtw_args))
  object$twdtw_args[matching_twdtw_args] <- new_twdtw_args[matching_twdtw_args]

  # Convert newdata to an array with the dimensions time series, time, and band.
  # In a data cube the missing values remain missing
  is_data_cube <- inherits(newdata, "stars")
  if (is_data_cube) {
    if (length(dim(newdata)) != 3 || !'time' %in% names(dim(newdata))) {
      stop("newdata must be a three-dimensional stars object with a 'time' dimension")
    }
    newdata_ts <- data_cube_array(newdata)
  } else {
    newdata_ts <- time_series_array(newdata)
  }

  # The time series must have the bands of the temporal patterns
  patterns <- lapply(object$data$observations, as.data.frame)
  pattern_bands <- setdiff(names(patterns[[1]]), 'time')
  newdata_bands <- dimnames(newdata_ts$values)[[3]]
  if (!setequal(newdata_bands, pattern_bands)) {
    stop(paste0("The bands of newdata (", paste(newdata_bands, collapse = ", "),
                ") are not the bands of the model (", paste(pattern_bands, collapse = ", "), ")"))
  }

  # Find the nearest temporal pattern of each time series
  nearest_neighbor <- twdtw_knn(x = newdata_ts$values,
                                y = patterns,
                                time = newdata_ts$time,
                                time_weight = object$twdtw_args$time_weight,
                                cycle_length = object$twdtw_args$cycle_length,
                                time_scale = object$twdtw_args$time_scale,
                                origin = object$twdtw_args$origin,
                                max_elapsed = object$twdtw_args$max_elapsed)

  # Label of the nearest pattern and the distance to it
  prediction <- factor(object$data$label[nearest_neighbor$index[, 1]])
  distance <- nearest_neighbor$distance[, 1]

  # A data cube returns a map with its spatial dimensions
  if (is_data_cube) {
    space_dims <- which(names(dim(newdata)) != 'time')
    map_dim <- dim(newdata)[space_dims]
    return(st_as_stars(list(prediction = structure(prediction, dim = map_dim),
                            distance = structure(distance, dim = map_dim)),
                       dimensions = st_dimensions(newdata)[space_dims]))
  }

  return(data.frame(prediction = prediction, distance = distance))
}
